INSERT INTO quarterly_kra_approvals (member_id,approved_by,approved_at,remarks,ratings_json,rater_signature_data,rater_signed_at) VALUES (976281,920002,'2026-10-08 09:00:00','Synthetic review for Amara Bautista: checked the property register evidence and reconciled 15 sampled work records. Property register needs clearer follow-up; retain source references and review the next four weekly logs.','[{"score_id":966251,"criterion_name":"Property register","kpi_description":"AP Manager I: lead and validate assigned property register. Reconcile 100% of assigned property records monthly; resolve differences within 5 working days.","weight":5,"self_rating":2,"rating":2},{"score_id":966252,"criterion_name":"Title completeness","kpi_description":"AP Manager I: lead and validate assigned title completeness. Verify title and tax documents for every assigned case before endorsement.","weight":5,"self_rating":3,"rating":3},{"score_id":966253,"criterion_name":"Valuation evidence","kpi_description":"AP Manager I: lead and validate assigned valuation evidence. Obtain two current comparable transactions for each valuation recommendation.","weight":5,"self_rating":3,"rating":3},{"score_id":966254,"criterion_name":"Disposition milestones","kpi_description":"AP Manager I: lead and validate assigned disposition milestones. Complete at least 90% of approved disposition milestones by due date.","weight":5,"self_rating":4,"rating":4},{"score_id":966255,"criterion_name":"Buyer due diligence","kpi_description":"AP Manager I: lead and validate assigned buyer due diligence. Complete identity and funding checks before every buyer endorsement.","weight":5,"self_rating":3,"rating":2},{"score_id":966256,"criterion_name":"Site inspection","kpi_description":"AP Manager I: lead and validate assigned site inspection. Document condition, occupancy and hazards for every scheduled inspection.","weight":5,"self_rating":3,"rating":3},{"score_id":966257,"criterion_name":"Occupancy monitoring","kpi_description":"AP Manager I: lead and validate assigned occupancy monitoring. Update occupied-property follow-ups weekly and escalate overdue cases within 2 days.","weight":5,"self_rating":3,"rating":3},{"score_id":966258,"criterion_name":"Broker coordination","kpi_description":"AP Manager I: lead and validate assigned broker coordination. Record broker leads and follow up qualified enquiries within 2 working days.","weight":5,"self_rating":2,"rating":2},{"score_id":966259,"criterion_name":"Tax obligations","kpi_description":"AP Manager I: lead and validate assigned tax obligations. Maintain a deadline register with no missed assigned tax filing dates.","weight":5,"self_rating":4,"rating":4},{"score_id":966260,"criterion_name":"Case documentation","kpi_description":"AP Manager I: lead and validate assigned case documentation. Index all signed case documents within 2 working days of receipt.","weight":5,"self_rating":3,"rating":3},{"score_id":966261,"criterion_name":"Collection tracking","kpi_description":"AP Manager I: lead and validate assigned collection tracking. Reconcile scheduled buyer payments weekly and flag arrears within 1 day.","weight":5,"self_rating":4,"rating":4},{"score_id":966262,"criterion_name":"Portfolio reporting","kpi_description":"AP Manager I: lead and validate assigned portfolio reporting. Deliver monthly portfolio report by the fifth working day with no material errors.","weight":5,"self_rating":3,"rating":2},{"score_id":966263,"criterion_name":"Client enquiries","kpi_description":"AP Manager I: lead and validate assigned client enquiries. Answer at least 95% of assigned client enquiries within 2 working days.","weight":5,"self_rating":3,"rating":3},{"score_id":966264,"criterion_name":"Legal escalation","kpi_description":"AP Manager I: lead and validate assigned legal escalation. Refer all identified legal exceptions with complete evidence within 2 days.","weight":5,"self_rating":3,"rating":3},{"score_id":966265,"criterion_name":"Asset safeguarding","kpi_description":"AP Manager I: lead and validate assigned asset safeguarding. Close critical property safety findings within approved response dates.","weight":5,"self_rating":3,"rating":3},{"score_id":966266,"criterion_name":"Expense control","kpi_description":"AP Manager I: lead and validate assigned expense control. Explain all acquisition/disposition cost variances exceeding 5%.","weight":5,"self_rating":4,"rating":4},{"score_id":966267,"criterion_name":"Team delivery","kpi_description":"AP Manager I: lead and validate assigned team delivery. Review assigned case workloads fortnightly and redistribute overdue tasks.","weight":5,"self_rating":3,"rating":3},{"score_id":966268,"criterion_name":"Policy implementation","kpi_description":"AP Manager I: lead and validate assigned policy implementation. Document quarterly compliance checks for every assigned property process.","weight":15,"self_rating":3,"rating":3}]',NULL,NULL);
